#include "ksMidiFileEventTask.h"
#include <array>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::MidiFileEventTask;using S=T::Stage;using C=T::Child;using K=T::Kind;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}int main(){try{uint64_t cases=0;auto verify=[&](unsigned kind,unsigned byte,unsigned count,uint32_t length,uint32_t base){T t{K(kind),base,uint8_t(byte)};constexpr std::array<uint8_t,10>types{0,1,2,3,4,5,6,7,47,81};std::vector<uint8_t>sent;unsigned meta=0,vlq=0,tempo=0,decode=0,publish=0;uint32_t cursor=base;bool expectMeta=false;while(!t.complete()&&!t.handoff()){if(t.awaitingChild()){auto c=t.child();if(c==C::Send)sent.push_back(t.byte());if(c==C::Decode){++decode;check(t.byte()==byte,"File decodebyte");}if(c==C::Vlq){++vlq;check(t.resumeVlq(length,t.stream()+2),"File VLQreply");}else if(c==C::Meta){++meta;expectMeta=true;check(t.descriptor()<types.size()&&types[t.descriptor()]==byte,"File meta selection");check(t.resumeMeta(t.stream()+9),"File metareply");}else{if(c==C::Tempo){++tempo;check(t.tempo()==((byte<<16)|(count<<8)|uint8_t(length)),"File tempo24 packing");}check(t.resumeChild(),"File voidreply");}continue;}auto read=[&](S s)->uint32_t{switch(s){case S::EventRead:case S::MetaRead:return byte;case S::EventReadStatusCount:case S::EventReadDataCount:return count;case S::MetaReadCandidate:return types[t.descriptor()];case S::MetaReadHandler:return 0xdeadbeef;case S::MetaReadSkip:return length&255;case S::TempoReadLength:return 3;case S::TempoReadHigh:return byte;case S::TempoReadMiddle:return count;case S::TempoReadLow:return length&255;default:return uint8_t(t.stream()-base);}};auto write=[&](S s,uint32_t v){check(s==S::EndPublish&&v==0,"File end publication");++publish;};auto before=t.stage();auto cost=t.nextClocks(6);check(cost&&t.advanceBefore(cost-1,read,write,[](S){return 6u;})==0&&before==t.stage(),"Early fileevent deadline");check(t.advanceBefore(cost,read,write,[](S){return 6u;})==cost,"Fileevent deadline");}
if(kind==0){if(byte==255||byte==240||byte==247){check(t.handoff()&&t.route()==(byte==255?T::Route::Meta:byte==240?T::Route::Start:T::Route::Continue)&&sent.empty()&&t.stream()==base+1,"File event specialtail");}else{unsigned n=byte<128?(count?count:256):count;check(sent.size()==n+(byte>=128),"File event count including zero256");if(byte>=128)check(sent[0]==byte,"File status first");check(t.stream()==base+n+(byte>=128),"File event cursor");}}
else if(kind==1){bool known=false;for(auto type:types)known|=type==byte;check(meta==unsigned(known),"File meta dispatch");check(t.stream()==base+(known?10:2+(length&255)),"File meta skip/replycursor");}
else if(kind==2)check(vlq==1&&t.stream()==base+2+length,"File skip VLQ unsignedwrap");else if(kind==3)check(tempo==1&&t.stream()==base+4,"File tempo cursor");else if(kind==4)check(publish==1&&t.stream()==base,"File End");else if(kind==5||kind==6){check(vlq==1&&sent.size()==length+(kind==5),"File SysEx length");if(kind==5)check(sent[0]==240,"File SysEx start");check(t.stream()==base+2+length,"File SysEx source");}else check(decode==1&&t.stream()==base,"File wrapper retainedstream");++cases;};
for(unsigned byte=0;byte<256;++byte)for(unsigned count=0;count<256;++count){verify(0,byte,count,3,0xfffffffeu);verify(1,byte,count,byte,0xfffffffeu);verify(3,byte,count,uint8_t(byte+count),0xfffffffeu);verify(7,byte,count,3,0xfffffffeu);}for(unsigned length=1;length<=256;++length)for(unsigned kind:{2u,5u,6u})verify(kind,0,0,length,0xfffffffdu);for(uint32_t length:{0u,0x7fffffffu,0x80000000u,0xffffffffu})verify(2,0,0,length,0xfffffffdu);verify(4,0,0,0,0xffffffffu);
T zero{K::Continue,0xffffffffu};while(zero.stage()!=S::ContinueAdmit){if(zero.awaitingChild()){if(zero.child()==C::Vlq)zero.resumeVlq(0,0xffffffffu);else zero.resumeChild();}else{auto read=[](S){return 0u;};auto write=[](S,uint32_t){};zero.advanceBefore(zero.nextClocks(3),read,write,[](S){return 3u;});}}check(zero.remaining()==0xffffffffu&&!zero.complete(),"Zero SysEx length must preserve original unsigned loop");++cases;
std::cout<<"PASS: "<<cases<<" pure MIDI-file event/meta/SysEx tasks, independent status/count/zero256/metadata/tempo/unsigned cursor oracles, typed child replies, zero32-bit SysEx loop checkpoint and early deadlines\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
